-- Schema minimo realista, exclusivamente para Testcontainers
CREATE TABLE tb_enderecos (id_endereco INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,cep VARCHAR(10),estado CHAR(2),cidade VARCHAR(100),logradouro VARCHAR(150),numero VARCHAR(20),complemento VARCHAR(100));
CREATE TABLE tb_lkp_tipos_usuarios (id_tipo_usuario INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,nome_tipo VARCHAR(50) NOT NULL,descricao VARCHAR(255));
CREATE TABLE tb_usuarios (id_usuario INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,nome_usuario VARCHAR(100) NOT NULL,email_usuario VARCHAR(255) NOT NULL,senha_hash VARCHAR(255) NOT NULL,data_nascimento DATE,cpf VARCHAR(11),url_avatar VARCHAR(500),ativo BOOLEAN NOT NULL DEFAULT TRUE,registro_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),tipo_usuario_id INTEGER NOT NULL REFERENCES tb_lkp_tipos_usuarios(id_tipo_usuario),endereco_id INTEGER NOT NULL REFERENCES tb_enderecos(id_endereco));
CREATE TABLE tb_autenticacoes_api (id_autenticao_api INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,usuario_id INTEGER NOT NULL REFERENCES tb_usuarios(id_usuario),token TEXT NOT NULL UNIQUE,tipo_token VARCHAR(20) NOT NULL DEFAULT 'Bearer' CHECK (tipo_token='Bearer'),criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),expira_em INTEGER NOT NULL CHECK (expira_em>0));
